from datetime import datetime, timedelta, timezone


def daily_counts(events, offset_minutes=0):
    if not -1439 <= offset_minutes <= 1439:
        raise ValueError("offset must be less than 24 hours")
    target = timezone(timedelta(minutes=offset_minutes))
    counts = {}
    for event in events:
        parsed = datetime.fromisoformat(event.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            raise ValueError("timestamp must include timezone")
        local = parsed.replace(tzinfo=target)
        day = local.date().isoformat()
        counts[day] = counts.get(day, 0) + 1
    return dict(sorted(counts.items()))

