import unittest
from solution import daily_counts

class VisibleTests(unittest.TestCase):
    def test_eastward_midnight_crossing(self):
        self.assertEqual(daily_counts(["2026-01-31T20:30:00Z"], 480), {"2026-02-01": 1})

    def test_westward_year_crossing(self):
        self.assertEqual(daily_counts(["2026-01-01T01:00:00+00:00"], -300), {"2025-12-31": 1})

    def test_counts_same_utc_day(self):
        self.assertEqual(daily_counts(["2026-03-10T01:00:00Z", "2026-03-10T23:00:00Z"]), {"2026-03-10": 2})

