import unittest
from solution import daily_counts

class HiddenTests(unittest.TestCase):
    def test_source_offset_and_fractional_hour_target(self):
        self.assertEqual(daily_counts(["2026-03-02T01:00:00+09:00"], 330), {"2026-03-01": 1})
        self.assertEqual(daily_counts(["2026-03-01T23:30:00-02:00"]), {"2026-03-02": 1})

    def test_exact_midnight_and_sorted_keys(self):
        result = daily_counts(["2026-04-02T23:00:00Z", "2026-04-01T23:00:00Z", "2026-04-01T22:59:59Z"], 60)
        self.assertEqual(result, {"2026-04-01": 1, "2026-04-02": 1, "2026-04-03": 1})
        self.assertEqual(list(result), ["2026-04-01", "2026-04-02", "2026-04-03"])

    def test_naive_and_invalid_offset(self):
        with self.assertRaises(ValueError):
            daily_counts(["2026-01-01T12:00:00"])
        for offset in (-1440, 1440):
            with self.subTest(offset=offset), self.assertRaises(ValueError):
                daily_counts([], offset)

    def test_empty_and_equivalent_instants(self):
        self.assertEqual(daily_counts([], 480), {})
        self.assertEqual(daily_counts(["2026-01-01T00:00:00Z", "2025-12-31T19:00:00-05:00"]), {"2026-01-01": 2})
